create table if not exists public.buildpulse_outbound_conversions(id uuid primary key default gen_random_uuid(),partner_id uuid not null references public.buildpulse_outbound_partners(id) on delete restrict,click_id uuid references public.buildpulse_outbound_clicks(id) on delete set null,external_conversion_id text not null,conversion_type text not null default 'affiliate',gross_value numeric,commission_amount numeric,currency text not null default 'USD',status text not null default 'pending' check(status in('pending','approved','reversed','paid','rejected')),occurred_at timestamptz,reported_at timestamptz not null default now(),approved_at timestamptz,paid_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(partner_id,external_conversion_id));
create table if not exists public.buildpulse_outbound_webhook_events(id uuid primary key default gen_random_uuid(),partner_id uuid references public.buildpulse_outbound_partners(id) on delete set null,provider text not null,external_event_id text not null,payload_hash text not null,signature_verified boolean not null default false,status text not null default 'received' check(status in('received','processed','rejected','failed')),received_at timestamptz not null default now(),processed_at timestamptz,error text,unique(provider,external_event_id));
alter table public.buildpulse_outbound_conversions enable row level security;alter table public.buildpulse_outbound_webhook_events enable row level security;revoke all on public.buildpulse_outbound_conversions,public.buildpulse_outbound_webhook_events from anon,authenticated;grant all on public.buildpulse_outbound_conversions,public.buildpulse_outbound_webhook_events to service_role;
alter table public.buildpulse_outbound_partners add column if not exists tracking_domain text,add column if not exists application_url text,add column if not exists contact_email text,add column if not exists program_terms_url text,add column if not exists network text,add column if not exists last_verified_at timestamptz;